            # General case
            if coeff > 0:
                sign = "+"
                coeff_str = str(coeff)
            else:
                sign = "-"
                coeff_str = str(abs(coeff))
            if degree == 1:
                term_str = sign + coeff_str + "x"
            else:
                term_str = sign + coeff_str + f"x^{degree}"

        terms.append(term_str)

    if not terms:
        return "0"

    # Join the terms, handling the first term specially
    result = terms[0]
    for term in terms[1:]:
        result += term

