def calculate_score(system: int, points: str) -> list:
    games = []
    player_score = 0
    opponent_score = 0

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1

        # Check if the game is finished
        # A game ends when someone reaches 'system' points AND has at least a 2-point lead
        if (player_score >= system or opponent_score >= system) and abs(player_score - opponent_score) >= 2:
            games.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    # If there are points left in the current game (mid-game), add the current score
    if player_score > 0 or opponent_score > 0:
        games.append(f"{player_score}:{opponent_score}")

    return games

