            if heights[j] < heights[i]:
                lis_forward[i] = max(lis_forward[i], lis_forward[j] + 1)

    # Calculate the longest decreasing subsequence starting at each index
    lis_backward = [1] * n
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if heights[i] > heights[j]:
                lis_backward[i] = max(lis_backward[i], lis_backward[j] + 1)

    # Find the maximum length of a valid choir formation using each position as the peak
    max_formation = 0
    for i in range(n):
        # The peak can be at position i
        # The height at i is part of both the increasing and decreasing subsequences
        # To avoid double counting the peak, we do: lis_forward[i] + lis_backward[i] - 1
        formation_length = lis_forward[i] + lis_backward[i] - 1
        max_formation = max(max_formation, formation_length)

    return n - max_formation
