def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Calculate Longest Increasing Subsequence (LIS) ending at each index
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Calculate Longest Decreasing Subsequence (LDS) starting at each index
    lds = [1] * n
    for i in range(n-2, -1, -1):
        for j in range(n-1, i, -1):
            if heights[i] > heights[j]:
                lds[i] = max(lds[i], lds[j] + 1)

    # The maximum choir size is the maximum sum of L
    # Note: We subtract 1 because the peak student is counted in both LIS and LDS
    max_choir_size = 0
    for i in range(n):
        choir_size = lis[i] + lds[i] - 1
        max_choir_size = max(max_choir_size, choir_size)

    return n - max_choir_size

